export type OperationalProtocolStep = typeof ENEA_OPERATIONAL_PROTOCOL[number];
export type SystemRegistryStep = "runner_lifecycle" | "checkpoint_persistence" | "external_gate";
export type RegistryStep = OperationalProtocolStep | SystemRegistryStep;

export interface OperationalRegistryRule {
  id: string;
  step: RegistryStep;
  kind?: "business" | "system";
  condition: string;
  sourcePrecedence: readonly string[];
  deterministicAction: string;
  audit: string;
  outcome: "continue" | "requested_operator";
  priority?: number;
  provenance?: Readonly<{
    authority: "user";
    receivedAt: string;
    source: "delegated_user_instruction";
    sourceRef?: string;
  }>;
  lifecycle?: Readonly<{
    status: "active" | "historical_override_non_propagable" | "superseded";
    generalGateEligible: boolean;
    supersededByRuleId?: string;
    note: string;
  }>;
}

