    step: "runner_lifecycle",
    kind: "business",
    condition: "Il percorso Infissi termina OPERATOR_REQUIRED con una domanda gia formulata dalla revisione profonda o ricavabile deterministicamente dal blocker.",
    sourcePrecedence: ["operatorQuestion persistita nel blocker Infissi", "testo deterministico per codice blocker", "domanda generica soltanto come fallback esplicito"],
    deterministicAction: "Far leggere al generatore anche il checkpoint Infissi e persistere la domanda nel registro strutturato prima di pubblicare OPERATOR_REQUIRED. Un verdetto operatore senza domanda persistita non e terminale valido.",
    audit: "practiceId/customerKey, blocker Infissi, testo domanda, sourceIds, revision registro e ID regola.",
