    deterministicAction: "Persistire null per larghezza, altezza e unita e formulare una domanda operatore. Vietare 1x1 mm e qualunque altro numero sintetico usato soltanto per soddisfare uno schema; nessun payload ENEA puo contenere il segnaposto.",
