    condition: "Checkpoint esecuzione e stato servizio concordano su completed, non esiste una pratica corrente e un worker o servizio della stessa coorte terminale continua a contendere il controller browser.",
    sourcePrecedence: ["checkpoint esecuzione completed senza currentCustomerKey", "stato servizio completed", "identita esatta della coorte e dei suoi servizi", "processo e lease globale osservati"],
    deterministicAction: "Il worker rilascia il controller e termina pulitamente; il LaunchAgent non lo rilancia dopo uscita riuscita. Codex puo rendere quiescenti worker, supervisore e watchdog gia terminali senza nuova conferma. Non arrestare mai Chrome, keepalive o servizi non terminali; qualunque discordanza resta fail-closed.",
    audit: "coorte, PID e label esatti, stati execution/service, currentCustomerKey nullo, lease prima/dopo, exit status, Chrome e keepalive preservati, ID regola.",
