    sourcePrecedence: ["practiceId UUID esatto congelato nel manifest", "nome e cognome esatti come controllo di identita", "fase corrente restituita dal CRM soltanto come attributo auditato, mai come parte dell'identita"],
    deterministicAction: "Eseguire il GET read-only per practiceId senza filtro di fase e accettare il record soltanto se l'ID e il nome normalizzato coincidono entrambi. Conservare la fase corrente nell'audit e applicare successivamente le normali policy di ammissione/esclusione. Un ID assente, duplicato o associato a un'identita diversa resta fail-closed; la ricerca senza ID conserva i propri controlli di fase.",
