const migratedRules = Object.entries(OPERATIONAL_RULES).map(([field, action], index): OperationalRegistryRule => ({
  id: `authorized-${String(index + 1).padStart(2, "0")}-${field.replace(/[^a-z0-9]+/gi, "-").toLowerCase()}`,
  step: field.startsWith("beneficiario") || field.startsWith("immobile") ? "identity_property"
    : field.startsWith("intervento") || field === "ricevuta_at" ? "dates"
    : field.startsWith("schermature") ? "screenings" : "plant",
  condition: `Campo ${field}: applicare quando la fonte specifica è assente o la regola ne definisce la gestione.`,
  sourcePrecedence: ["form cliente", "documento originario verificato", "policy operativa autorizzata"],
  deterministicAction: action,
  audit: `Registrare campo, fonte effettiva e ${ENEA_OPERATIONAL_REGISTRY_VERSION}.`,
  outcome: action.toLowerCase().includes("intervento operatore") || action.toLowerCase().includes("richiedono operatore") ? "requested_operator" : "continue",
}));

// Invarianti tecniche richieste dal runner. Non introducono decisioni sui dati
// della pratica: regolano esclusivamente persistenza, concorrenza e fail-safe.
export const ENEA_RUNNER_SYSTEM_RULES: readonly OperationalRegistryRule[] = Object.freeze([
  { id:"system-user-decision-general-candidate-default-v1", kind:"system", step:"checkpoint_persistence", condition:"Giuliano risponde a una domanda operatore o formula una decisione che può descrivere un pattern riutilizzabile", sourcePrecedence:["testo originale della decisione utente", "domanda e prove documentali che l'hanno originata", "scope esplicitamente dichiarato dall'utente"], deterministicAction:"Registrare atomicamente la decisione come candidate generale. Lo scope case_only è ammesso soltanto con dichiarazione esplicita; la candidata non modifica pratiche finché non possiede regola generale, test positivo/negativo, matrice, gate e bundle certificato.", audit:"decisionId, testo, pattern normalizzato, input semantici, fonte, evidenza caso separata, stato e timestamp", outcome:"continue" },
  { id:"system-rule-governance-execution-admission-v1", kind:"system", step:"external_gate", condition:"Un processo APR sta per iniziare elaborazione automatica o collegarsi al controller mutativo ENEA", sourcePrecedence:["fingerprint del registro compilato nel bundle", "fingerprint della matrice compilata nel bundle", "fingerprint del registro decisioni compilato nel bundle", "attestazione laterale e SHA-256 del bundle in esecuzione"], deterministicAction:"Rifiutare l'avvio mutativo se anche un solo fingerprint, versione, conteggio di prove o SHA-256 non coincide. L'assenza dell'attestazione chiude il gate; dashboard e keepalive read-only restano separati.", audit:"ruolo bundle, path, SHA-256, versioni registro/matrice/decisioni, fingerprint attesi/osservati, esito e timestamp", outcome:"continue" },
  { id:"system-rule-evidence-recognition-end-to-end-v1", kind:"system", step:"external_gate", condition:"Una decisione di business viene candidata alla certificazione generale", sourcePrecedence:["documento originale o fixture fedele", "riconoscimento dell'evidenza nella pipeline reale", "azione deterministica della regola", "caso negativo indipendente"], deterministicAction:"Certificare soltanto se il test positivo attraversa acquisizione/riconoscimento/normalizzazione/regola/esito e il negativo prova il fail-closed. Un test della sola funzione di policy non basta a dichiarare copertura end-to-end.", audit:"decisionId, ruleId, fixture positiva, fixture negativa indipendente, executionPath, campi prodotti, report grezzo e fingerprint", outcome:"continue" },
  { id:"system-canonical-executable-draft-package-v1", kind:"system", step:"checkpoint_persistence", condition:"Un preflight verde consegna al bridge e al worker il pacchetto che verra eseguito sul portale", sourcePrecedence:["checkpoint preflight terminale", "pacchetto completo dopo il bridge economico", "manifest immutabile legato al fingerprint fonti", "SHA-256 dei byte consumati dal worker"], deterministicAction:"Costruire una sola volta il pacchetto eseguibile dopo tutti i gate, persisterlo atomicamente con hash e far consumare al worker soltanto quegli stessi byte. Vietare la ricostruzione durante heartbeat, claim, ripresa o finalizzazione; artefatto assente, alterato o discordante chiude il gate senza azioni ENEA.", audit:"cohortRoot, sourceFingerprint, customerKey, practiceId, packageFingerprint, workflowFingerprint, artifactPath, artifactSha256, esito rilettura e ID regola", outcome:"continue" },
  { id:"system-operator-question-configurable-delivery-v1", kind:"system", step:"runner_lifecycle", condition:"Una pratica ha un solo dato mancante o ambiguo e APR ha persistito una domanda operatore strutturata", sourcePrecedence:["checkpoint locale della domanda", "outbox locale atomica", "sink di notifica configurato separatamente", "risposta operatore persistita"], deterministicAction:"Scrivere sempre la domanda in un artefatto locale prima della consegna; notificare tramite il sink configurato in modo idempotente, senza scrivere o spostare nulla nel CRM. Un errore del sink conserva pending e ritenta; una risposta deterministica riapre soltanto il checkpoint del caso, mentre un secondo dubbio genera un nuovo giro.", audit:"questionId, customerKey, field, exactCause, missingDocumentType, operatorQuestion, onboardingGap, percorso outbox, destinazione, tentativi, esito e ID regola", outcome:"continue" },
  { id:"system-infissi-required-revisions-durable-convergence-v1", kind:"system", step:"checkpoint_persistence", condition:"Piu processi possono completare il preflight Infissi mentre il gate installa in sequenza tutte le revisioni obbligatorie", sourcePrecedence:["checkpoint Infissi riletto dopo ogni passaggio", "insieme versionato delle revisioni obbligatorie", "audit di ogni ricalcolo completato"], deterministicAction:"Rileggere il checkpoint durevole, applicare soltanto le revisioni mancanti e ripetere per un numero limitato di passaggi. Aprire il bridge soltanto quando tutte le revisioni sono presenti contemporaneamente; se anche una sola non diventa durevole, fallire chiuso senza azioni ENEA.", audit:"revisioni richieste, revisioni osservate per passaggio, marker recuperati, postcondizione e ID regola", outcome:"continue" },
  { id:"system-cohort-seed-atomic-fresh-generation-initialization-v1", kind:"system", step:"checkpoint_persistence", condition:"Uno o piu processi APR possono inizializzare o preparare enea-draft-execution mentre il cohort seed immutabile dichiara fresh_generation", sourcePrecedence:["cohort-seed/checkpoint.json atomico e immutabile", "policy fresh_generation con experimentId valido", "checkpoint execution ancora privo di bozze", "override esplicito soltanto se concordante col seed"], deterministicAction:"Rileggere la policy autorevole dal cohort seed a ogni confine che puo creare o aggiungere item di esecuzione, anche se l'istanza o il checkpoint vuoto esistevano prima del seed. Marcare ogni nuovo item requiresFreshDraft=true; rifiutare seed illeggibili, policy invalide e override discordanti. In assenza della policy mantenere false senza adottare bozze storiche per una coorte fresca.", audit:"root coorte, experimentId, momento initialize/prepare/append, requiresFreshDraft prodotto, eventuale mismatch, ID regola", outcome:"continue" },
  { id:"system-verified-package-recovery-accounting-candidate-separation-v1", kind:"system", step:"checkpoint_persistence", condition:"Il worker osserva save_intent_recorded durante un recupero autorizzato e deve decidere se applicare il repair contabile riservato a un pacchetto Infissi corretto oppure proseguire con la normale sonda server", sourcePrecedence:["audit verified_infissi_package_correction_requeued della stessa pratica", "audit page_save_intent_recorded successivo", "checkpoint della stessa bozza canonica", "evidenceId della correzione distinto dalle vecchie sonde"], deterministicAction:"Invocare il repair contabile soltanto se esiste l'audit di correzione pacchetto precedente all'intento corrente e tutte le altre precondizioni coincidono. Un recupero ordinario senza tale audit non viene modificato e prosegue direttamente alle sonde server read-only; uno stato ambiguo resta fail-closed.", audit:"customerKey, canonicalDraftId, revisioni audit correzione/intento, evidenceId, contatori, candidato si/no e ID regola", outcome:"continue" },
  { id:"system-verified-package-recovery-intent-accounting-v1", kind:"system", step:"checkpoint_persistence", condition:"Un pacchetto corretto e verificato ha gia consumato il proprio Salva sulla bozza canonica, ma il checkpoint conserva zero recuperi perche eredita l'incertezza della generazione precedente", sourcePrecedence:["checkpoint della bozza canonica", "audit correzione pacchetto", "intento Salva successivo", "evidenceId della correzione distinto dalle vecchie sonde"], deterministicAction:"Contabilizzare quel Salva gia tentato come unico recupero e consentire soltanto la verifica server read-only; non premere nuovamente Salva e non creare una nuova bozza.", audit:"customerKey, generationId, canonicalDraftId, pagina, evidenceId vecchi e corrente, contatori prima/dopo, ID regola", outcome:"continue" },
  { id:"system-checkpoint-roundtrip-fail-closed-restore-v1", kind:"system", step:"checkpoint_persistence", condition:"Un checkpoint esistente non supera lettura, normalizzazione o validazione, oppure deve essere ricostruito dopo una reinizializzazione provata", sourcePrecedence:["checkpoint persistente", "mapping CDP della bozza", "journal worker", "audit servizio", "fingerprint della fonte congelata"], deterministicAction:"Rifiutare il caricamento senza sostituire il file; ricostruire la stessa generazione e bozza canonica soltanto con tre prove indipendenti concordanti, mantenere consumato l'unico Salva e autorizzare esclusivamente una verifica server read-only.", audit:"hash e revisione checkpoint, generationId, canonicalDraftId, tre evidenceId indipendenti, contatori, esito round-trip", outcome:"continue" },
  { id:"system-sequencer-nonterminal-continuous-observation-v1", kind:"system", step:"runner_lifecycle", condition:"Il worker resta in probing, recovery_queued, filling o save_intent_recorded mentre il sequencer attende la verita finale", sourcePrecedence:["checkpoint execution corrente", "heartbeat worker/watchdog", "lifecycle salvataggio incerto", "snapshot dashboard"], deterministicAction:"Mantenere il sequencer in monitoraggio con heartbeat e senza scadenza mutativa finche due osservazioni concordanti producono una verita terminale. Non pubblicare il non-terminale come verdetto, non trasformare una finestra di osservazione in stop globale e non arrestare worker, watchdog, keepalive o Chrome.", audit:"customerKey, stato non terminale, heartbeat sequencer, fingerprint osservazioni, stato servizi e ID regola", outcome:"continue" },
  { id:"system-sequencer-deep-review-terminal-gate-v1", kind:"system", step:"runner_lifecycle", condition:"Un preflight comune o prodotto ha scritto blocked_case mentre la revisione profonda indipendente deve ancora classificare le stesse prove", sourcePrecedence:["report.blockers persistente del preflight applicabile al modulo", "checkpoint deep-case-review terminale", "insieme esatto dei blocker classificati", "snapshot terminale atomico"], deterministicAction:"Non pubblicare alcun verdetto terminale finche la revisione profonda non e completed e il suo item non e terminale. Richiedere identita esatta dell'insieme blocker; mappare TECHNICAL_REPAIR a TECHNICAL_BLOCK e OPERATOR_REQUIRED/BUSINESS_RULE_REQUIRED a OPERATOR_REQUIRED. AUTO_RESOLVED con preflight ancora bloccato, classificazioni incoerenti o blocker divergenti producono esclusivamente INCONSISTENT. Il supervisore non viene spento mentre la revisione e queued, reviewing o working.", audit:"customerKey, modulo, revision/fingerprint preflight, stato/revisione/fingerprint deep review, blocker dei due lati, classificazione, terminal snapshotId, case-truth e ID regola", outcome:"continue" },
  { id:"system-infissi-recovery-candidate-transition-parity-v1", kind:"system", step:"checkpoint_persistence", condition:"Il worker valuta un recupero Infissi da GET canonica vuota prima di invocare la transizione persistente", sourcePrecedence:["checkpoint execution corrente", "uncertainPageSave corrente", "contatori save/recovery di ogni riga", "stato riepilogo Infissi"], deterministicAction:"Selezionare il candidato soltanto quando soddisfa integralmente lo stesso contratto della transizione: prefisso tentato una volta, zero recuperi consumati, suffisso intatto e riepilogo mai salvato. Un recupero gia consumato o qualunque stato discordante non viene reinvocato e non puo generare un ciclo tecnico o trattenere la lease globale.", audit:"customerKey, draftId, pageId, prefisso/suffisso, saveAttemptCount, recoverySaveAttemptCount, esito candidato e ID regola", outcome:"continue" },
  { id:"system-apr-continuity-no-orchestrator-stop-v1", kind:"system", step:"runner_lifecycle", condition:"Il sequencer osserva una pratica non terminale, prepara la successiva o conclude un test mentre keepalive e Chrome condiviso devono restare vivi", sourcePrecedence:["checkpoint execution stabile", "servizio worker persistente", "lease globale mutativa recintata", "snapshot terminale atomico"], deterministicAction:"Non arrestare mai una coorte non terminale dal sequencer. Pubblicare la verita soltanto dopo due osservazioni terminali identiche; quando execution e servizio concordano su completed senza pratica corrente, il worker deve rilasciare il controller e terminare pulitamente e i soli servizi della coorte terminale possono essere resi quiescenti. Keepalive e Chrome restano sempre vivi. Uno stato discordante resta fail-closed e non viene pubblicato come verdetto.", audit:"customerKey, servizi e PID osservati, due fingerprint terminali, snapshot pubblicato, lease globale, uscita pulita terminale oppure assenza di stop non terminale e ID regola", outcome:"continue" },
  { id:"system-generation-scoped-canonical-draft-v1", kind:"system", step:"checkpoint_persistence", condition:"APR apre volontariamente una nuova generazione di una pratica gia lavorata oppure riprende tecnicamente la generazione corrente", sourcePrecedence:["generationId persistente", "requiresFreshDraft della generazione attiva", "pending-create durevole della stessa impronta pacchetto", "canonicalDraftId della generazione"], deterministicAction:"Una nuova generazione non puo adottare mapping di generazioni precedenti: prima dell'intento crea una nuova bozza e, dopo un crash, puo scoprire soltanto la bozza non preesistente prodotta dal proprio pending-create. La ripresa tecnica usa esclusivamente canonicalDraftId e il primo checkpoint incompleto della stessa generazione. Le bozze precedenti restano superseded e non vengono mutate.", audit:"practiceId, customerKey, generationId, modalita nuova/ripresa, requiresFreshDraft, pending-create, beforeDraftIds, canonicalDraftId, generazioni superseded, evidenceId e ID regola", outcome:"continue" },
  { id:"system-sequencer-single-page-recovery-filling-lifecycle-v1", kind:"system", step:"checkpoint_persistence", condition:"Il worker ha reclamato un recovery_queued autorizzato da una sola prova persisted_fields_get=not_saved sulla stessa bozza e lo stato e passato a filling", sourcePrecedence:["checkpoint execution corrente", "prova server persisted_fields_get=not_saved sulla stessa URL e draftId", "recoveryAuthorizedEvidenceId della sola pagina", "budget recovery residuo"], deterministicAction:"Il sequencer mantiene il caso non terminale soltanto se la stessa prova server e persistita, esiste una sola pagina autorizzata, il tentativo primario e consumato e il budget recovery e ancora uno; ogni discordanza resta fail-closed.", audit:"customerKey, draftId, pageId, evidenceId, saveAttemptCount, recoverySaveAttemptCount, stato execution e ID regola", outcome:"continue" },
  { id:"system-sequencer-single-page-recovery-save-intent-lifecycle-v1", kind:"system", step:"checkpoint_persistence", condition:"Il worker ha emesso l'unico Salva di recupero autorizzato e ha persistito save_intent_recorded prima delle sonde read-only", sourcePrecedence:["checkpoint execution corrente", "prova server persisted_fields_get=not_saved della stessa bozza", "recoveryAuthorizedEvidenceId della sola pagina", "contatori primario uno e recovery uno"], deterministicAction:"Il sequencer mantiene il caso non terminale fino alla conclusione delle sonde soltanto se bozza, pagina e prova autorizzante coincidono, l'intento e persistito e l'unico budget recovery e appena consumato; ogni contatore, prova o pagina discordante chiude il gate.", audit:"customerKey, draftId, pageId, evidenceId, saveAttemptCount, recoverySaveAttemptCount, stato execution e ID regola", outcome:"continue" },
  { id:"system-sequencer-recoverable-transient-pre-save-observation-v1", kind:"system", step:"checkpoint_persistence", condition:"Una pratica conserva una bozza canonica ma il collegamento CDP si e interrotto prima di qualunque Salva sulla prima pagina pendente", sourcePrecedence:["checkpoint execution operator_intervention", "reason CDP transitorio tipizzato", "pageCheckpoints saved/staged/pending", "saveAttemptCount zero su almeno una pagina pendente"], deterministicAction:"Il sequencer non trasforma immediatamente l'errore storico in terminale e lascia al worker una sola ripresa tecnica prevista sulla stessa bozza; appena il caso esce dallo stato storico, un nuovo difetto CDP torna fail-closed e non viene mascherato.", audit:"customerKey, draftId, reason tipizzato, stati e contatori pagina, recoveryDeparted e ID regola", outcome:"continue" },
  { id:"system-invoice-customer-block-crm-cf-v1", kind:"system", step:"identity_property", condition:"Il modulo cartaceo e illeggibile sull'anagrafica, ma il CRM espone un CF formalmente valido e una fattura originaria contiene un blocco CLIENTE con lo stesso nominativo e CF", sourcePrecedence:["blocco CLIENTE entro la stessa pagina della fattura originaria", "CF CRM con checksum valido", "prefissi fiscali di nome e cognome CRM concordanti col CF"], deterministicAction:"Confermare il CF CRM soltanto quando nome e cognome compaiono insieme nel medesimo blocco CLIENTE, il CF etichettato coincide esattamente e i sei caratteri fiscali di cognome/nome concordano. Non attraversare confini pagina e non usare CF presenti solo in bonifici, causali o altre sezioni. Qualunque assenza o discordanza resta fail-closed.", audit:"customerKey, sourceId fattura, pagina, blocco CLIENTE, nome/cognome CRM, CF CRM, checksum, prefissi fiscali, esito e ID regola", outcome:"continue" },
  { id:"system-explicit-original-completion-date-v1", kind:"system", step:"dates", condition:"Il form CRM non contiene la fine lavori e una fonte originaria dichiara testualmente che i lavori di installazione/posa sono terminati oppure documenta un collaudo finale datato della posa in opera", sourcePrecedence:["data fine lavori esplicita e concordante nel form CRM", "dichiarazione originaria esplicita di completamento installazione/posa", "verbale originario di collaudo finale datato della posa", "ultima fattura solo come fallback"], deterministicAction:"Usare la data originaria esplicita prima del fallback fattura soltanto con frase causale completa e data di calendario valida. Un collaudo vale soltanto se dichiarato finale e riferito alla posa degli elementi installati. Date di fattura, pagamento, ordine, consegna, stampa o semplice descrizione fornitura/posa non valgono. Date esplicite divergenti, o conflitto col form CRM, producono blocker fail-closed.", audit:"customerKey, sourceId, tipo evidenza, data normalizzata, testo causale, eventuali date divergenti, fonte scelta, blocker o warning e ID regola", outcome:"continue", priority:1270 },
  { id:"system-invoice-multi-document-fiscal-segmentation-v2", kind:"system", step:"economic_sources", condition:"Un allegato o fascicolo fiscale contiene piu documenti autonomi, inclusi acconto/caparra e saldo con riga a detrarre", sourcePrecedence:["intestazioni fiscali complete numero/data per singola pagina o sezione", "marcatori di pagina del documento originario", "riferimenti espliciti ad acconto/caparra nelle fatture di saldo"], deterministicAction:"Segmentare ogni documento fiscale entro i confini di pagina o sezione, preservare tutte le terne numero/data/totale distinte e deduplicare soltanto identita fiscali concordanti. Una fattura di saldo che detrae un acconto non sostituisce ne autorizza a ignorare la fattura di acconto acquisita; se il richiamo esiste ma la fonte manca, fallire chiuso per la sola pratica.", audit:"documentKey, segmenti e pagine, identita fiscali, riferimenti acconto, deduplica, segmenti bancari esclusi e ID regola", outcome:"continue" },
  { id:"system-explicit-advance-invoice-reference-marker-v1", kind:"system", step:"economic_sources", condition:"Il testo di una fattura contiene la parola acconto, descrizioni della fattura corrente e importi del riepilogo che potrebbero essere scambiati per il numero di un'altra fattura", sourcePrecedence:["richiamo relazionale esplicito ad acconto/caparra", "marcatore fiscale N./NR/NUMERO adiacente al riferimento", "intestazione e riepilogo imponibile/IVA/totale della fattura corrente"], deterministicAction:"Creare un riferimento a una fattura di acconto distinta soltanto quando il testo contiene un marcatore esplicito di numero fiscale. Non interpretare mai come numero fattura un importo che segue Totale fattura, Imponibile o IVA. In assenza del marcatore non generare il blocker di fattura mancante; i richiami espliciti validi restano fail-closed se la fonte non e acquisita.", audit:"sourceId, frase candidata, marcatore fiscale, riferimento accettato, candidato monetario rifiutato e ID regola", outcome:"continue" },
  { id:"system-dimensioned-awning-row-preservation-v1", kind:"system", step:"screenings", condition:"Una fattura originaria contiene una riga Tenda da sole con modello, DIM. CM L larghezza x sporgenza SP e superficie MQ esplicita, ma non espone un gTot nella stessa riga", sourcePrecedence:["riga prodotto completa della fattura originaria", "misure L x SP etichettate in centimetri", "superficie MQ esplicita e coerente entro il 5%", "classificatore gTot condiviso"], deterministicAction:"Conservare una riga fisica con misure e superficie documentate e gTot nullo; demandare il solo gTot al classificatore fail-closed. Non generare prodotti da fatture di solo acconto, righe ACCONTO RIF. FATTURA o misure prive della descrizione Tenda da sole. Se superficie e misure non sono coerenti, non promuovere la riga e mantenere il gate chiuso.", audit:"sourceId, testo riga, modello, misure originali, superficie esplicita/calcolata, tolleranza, gTot nullo, esito e ID regola", outcome:"continue" },
  { id:"system-labelled-screening-depth-abbreviation-v1", kind:"system", step:"screenings", condition:"Una fattura originaria contiene una riga Pergotenda/Tenda da sole con larghezza L e sporgenza abbreviata S adiacenti, per esempio L 500 x S 290, ma senza gTot locale", sourcePrecedence:["riga prodotto originaria", "coppia L x S esplicitamente etichettata", "quantita esplicita valida oppure singolare non contraddetto", "classificatore gTot condiviso"], deterministicAction:"Conservare la riga fisica e normalizzare entrambe le misure con il risolutore di unita condiviso. Non accettare coppie numeriche prive delle due etichette, assi incomplete o quantita invalide; non anticipare i parser piu autorevoli quando gTot o superficie sono espliciti. Demandare il solo gTot mancante al classificatore fail-closed.", audit:"sourceId, testo prodotto, L/S originali, unita risolta, quantita, gTot locale assente, righe prodotte e ID regola", outcome:"continue" },
  { id:"system-specific-incomplete-screening-blocker-v1", kind:"system", step:"screenings", condition:"Almeno una riga fisica di schermatura e stata riconosciuta dalle fonti originarie, ma un attributo tecnico obbligatorio resta irrisolto", sourcePrecedence:["ledger delle righe fisiche riconosciute", "blocker specifico dell'attributo mancante", "blocker generico screenings_missing"], deterministicAction:"Conservare esclusivamente il blocker specifico dell'attributo irrisolto e non aggiungere screenings_missing. Aggiungere screenings_missing soltanto quando il ledger contiene zero righe fisiche; non rendere mai compilabile una riga incompleta.", audit:"numero righe fisiche, blocker specifici, blocker generico emesso o ritirato e ID regola", outcome:"continue" },
  { id:"system-explicit-percentage-causal-technical-supersession-v1", kind:"system", step:"screenings", condition:"Due fatture distinte descrivono lo stesso prodotto tecnico e le causali fiscali esplicite le identificano rispettivamente come acconto e saldo percentuali", sourcePrecedence:["CAUSALE DOCUMENTO o DATI AGGIUNTIVI della fattura", "parole AC­CONTO/SALDO ed eventuale percentuale entro la causale", "firma tecnica completa e ordine cronologico dei documenti"], deterministicAction:"Conservare entrambe le fatture nella riconciliazione economica ma usare soltanto il saldo per la cardinalita tecnica quando le righe dell'acconto sono un sottoinsieme delle righe del saldo. Parole acconto/saldo fuori dalle causali fiscali, firme tecniche incompatibili o cronologia inversa non autorizzano la fusione.", audit:"sourceId acconto/saldo, testo causale, percentuali, firme tecniche, esito sottoinsieme, righe tecniche ritirate e ID regola", outcome:"continue" },
  { id:"system-explicit-acconto-saldo-particle-technical-supersession-v1", kind:"system", step:"screenings", condition:"Due fatture distinte descrivono lo stesso prodotto e le intestazioni le qualificano esplicitamente come Fattura di/d'acconto e Fattura a saldo", sourcePrecedence:["intestazione fiscale del documento", "particelle relazionali di/d'acconto e a saldo", "firma tecnica completa", "ordine cronologico"], deterministicAction:"Conservare entrambe le fatture economicamente ma ritirare le sole righe tecniche dell'acconto quando sono un sottoinsieme di quelle del saldo. Un saldo che cita incidentalmente un acconto non puo diventare esso stesso acconto; parole isolate, firme incompatibili o ordine inverso restano fail-closed.", audit:"sourceId acconto/saldo, intestazioni, particelle, firme tecniche, cronologia, righe ritirate e ID regola", outcome:"continue" },
  { id:"system-zero-total-full-reversal-non-economic-v1", kind:"system", step:"gross_reconciliation", condition:"Una fattura o nota fiscale prova totale finale zero per effetto dello storno integrale esplicito di una fattura precedente", sourcePrecedence:["totale finale documento esplicitamente zero", "riga a detrarre/storno con riferimento alla fattura precedente", "identita fiscale del documento di storno"], deterministicAction:"Classificare il documento come rettifica non economica a impatto zero ed escluderlo dalla somma dei totali finali, conservandolo integralmente in audit. Non leggere imponibile o IVA; non applicare l'eccezione se il totale finale non e zero o il riferimento contabile e ambiguo.", audit:"numero/data, totale finale zero, riferimento stornato, motivo non_economic e ID regola", outcome:"continue" },
  { id:"system-resolved-non-economic-total-blocker-retirement-v1", kind:"system", step:"gross_reconciliation", condition:"Il parser documentale segnala totale non riconosciuto, ma il riconciliatore autorevole ha classificato esattamente tutti e soli i segmenti a totale nullo come storni non_economic e i totali finali delle fatture economiche sono verificati", sourcePrecedence:["elenco segmenti a totale nullo", "nonEconomicSourceIds", "finalPrintedTotalVerified"], deterministicAction:"Ritirare esclusivamente il blocker generico quando gli insiemi coincidono e persistere un warning auditabile. Se resta un segmento nullo non classificato, un totale finale non verificato o un messaggio diverso, conservare il blocker fail-closed.", audit:"messaggio originario, segmenti nulli, nonEconomicSourceIds, finalPrintedTotalVerified, totale finale e ID regola", outcome:"continue" },
  { id:"system-document-ocr-orientation-normalization-v1", kind:"system", step:"economic_sources", condition:"Un documento immagine richiede OCR locale e puo essere ruotato di 90, 180 o 270 gradi", sourcePrecedence:["quattro letture Vision locali della stessa pagina", "punteggio deterministico di segnali fiscali e leggibilita", "orientamento originale in caso di parita"], deterministicAction:"Eseguire OCR locale nelle quattro rotazioni, scegliere una sola lettura con il punteggio fiscale deterministico piu alto e persistere l'orientamento scelto nel testo. Ordinare le osservazioni nel sistema di coordinate della rotazione scelta (90: 1-y,x; 180: 1-x,1-y; 270: y,1-x), mai nel raster grezzo, affinche etichetta e valore restino sulla stessa riga/colonna semantica. Non inviare immagini a servizi esterni; se nessuna lettura supera i requisiti minimi, fallire chiuso.", audit:"documentKey, pagina, punteggi per orientamento, orientamento scelto, trasformazione coordinate, hash testo, modalita macos_vision_ocr e ID regola", outcome:"continue" },
  { id:"system-rotated-ocr-fiscal-reading-order-v1", kind:"system", step:"economic_sources", condition:"Una pagina OCR marcata 180 gradi restituisce le righe fiscali dal fondo verso l'alto", sourcePrecedence:["marker APR_OCR_ORIENTATION:180 persistito", "intestazione fiscale propria numero/data", "totale documento etichettato che precede l'intestazione nel testo OCR"], deterministicAction:"Invertire l'ordine delle sole righe della pagina quando e solo quando il marker 180 e il flusso fiscale intestazione-dopo-totale concordano; rieseguire segmentazione e terna sulla pagina normalizzata. Senza tutti gli ancoraggi conservare il testo originale e fallire chiuso.", audit:"documentKey, pagina, marker orientamento, indici intestazione/totale, normalizzazione applicata, identita fiscali prima/dopo e ID regola", outcome:"continue" },
  { id:"system-rotated-ocr-fiscal-reading-order-total-invoice-v2", kind:"system", step:"economic_sources", condition:"Una pagina OCR marcata 180 gradi espone l'intestazione fiscale dopo un totale etichettato TOTALE FATTURA", sourcePrecedence:["marker APR_OCR_ORIENTATION:180 persistito", "intestazione fiscale propria", "etichetta TOTALE FATTURA che precede l'intestazione nel flusso OCR"], deterministicAction:"Trattare TOTALE FATTURA come ancoraggio fiscale equivalente a TOTALE DOCUMENTO soltanto per provare il flusso 180 invertito; invertire la pagina e rieseguire identita, totale e riferimenti. Senza marker, intestazione o ordine invertito conservare il testo byte-per-byte e fallire chiuso.", audit:"documentKey, marker orientamento, indici TOTALE FATTURA/intestazione, testo normalizzato, identita e totale prima/dopo, ID regola", outcome:"continue" },
  { id:"system-native-ocr-fiscal-duplicate-authority-v1", kind:"system", step:"gross_reconciliation", condition:"Il fascicolo contiene un PDF nativo e una scansione OCR della stessa fattura, ma il totale OCR diverge per ordine tabellare", sourcePrecedence:["numero e data fiscali concordanti", "codice fiscale cliente concordante", "partita IVA concordante", "firma tecnica prodotto concordante", "totale del PDF nativo"], deterministicAction:"Ritirare la sola copia OCR soltanto se esiste un unico candidato PDF nativo con stesso numero, data, almeno un CF condiviso, almeno una P.IVA condivisa e firma tecnica non vuota identica. Se manca un ancoraggio, esistono piu candidati o le firme divergono, mantenere entrambe le fonti e fallire chiuso.", audit:"sourceId nativo/OCR, numero, data, token CF/P.IVA condivisi, firma tecnica, totali divergenti, candidato unico, sourceId ritirato e ID regola", outcome:"continue" },
  { id:"system-producer-position-table-infissi-v1", kind:"system", step:"screenings", condition:"Una dichiarazione originale del produttore dei nuovi serramenti espone la tabella Pos./Quantita/Descrizione/Valore Uw e ogni posizione contiene quantita, una coppia Largh./Alt. coerente e un Uw esplicito", sourcePrecedence:["documento originale dichiarazione del produttore", "posizione e quantita esplicite", "coppia Largh./Alt. ripetuta senza conflitti nello stesso blocco", "Uw calcolato esplicito nello stesso blocco"], deterministicAction:"Creare una riga fisica per ogni posizione e preservarne la quantita soltanto se tutte le posizioni sono complete e internamente coerenti. Se una posizione manca di quantita, L/H o Uw, oppure presenta valori discordanti, non produrre alcuna evidenza e mantenere il gate chiuso.", audit:"sourceId, posizione, quantita, coppie L/H osservate, Uw osservati, righe prodotte e ID regola", outcome:"continue" },
  { id:"system-single-product-energy-declaration-infissi-v1", kind:"system", step:"screenings", condition:"Una dichiarazione originale di conformita energetica degli infissi installati espone esattamente una tipologia con modello, dimensioni, pezzi e un solo Uw complessivo coerente", sourcePrecedence:["documento originale classificato third_party_certificate per installed_windows", "unica riga Rif. tipologia/Modello/dimensioni/pezzi", "unico valore esplicito della trasmittanza termica complessiva dei serramenti"], deterministicAction:"Creare una sola riga fisica con quantita, L/H e Uw documentati soltanto se la dichiarazione contiene una sola tipologia completa e un solo Uw. Piu tipologie, valori discordanti, scope non installato o campi mancanti mantengono il gate chiuso.", audit:"sourceId, scope certificato, numero tipologie, modello, quantita, L/H, valori Uw osservati, riga prodotta e ID regola", outcome:"continue" },
  { id:"system-parenthesized-uw-certificate-classification-v1", kind:"system", step:"screenings", condition:"Una dichiarazione di prestazione formale espone posizioni con quantita, misura da L x H e valore numerico come Trasmittanza termica (Uw)", sourcePrecedence:["documento originale", "profilo certificativo formale completo 5/5", "blocco Pos./Q.ta e misura da L x H", "etichetta Trasmittanza termica (Uw) e valore numerico plausibile", "norma tecnica e soggetto dichiarante"], deterministicAction:"Riconoscere la forma parentetica dell'etichetta Uw come prestazione numerica soltanto dentro un profilo certificativo completo; produrre righe solo se ogni posizione finestra contiene quantita, un'unica misura e un unico Uw nello stesso blocco. Accessori espliciti a 0 x 0 sono esclusi; una posizione finestra incompleta chiude l'intera estrazione. La sola presenza di etichetta e numero non promuove mai un allegato generico.", audit:"sourceId, storageKind, criteri certificativi, posizioni, quantita, misure, valori Uw, accessori 0 x 0 esclusi, profilo ed esito", outcome:"continue" },
  { id:USER_AUTHORIZED_RULE_IDS.technicalDocumentPracticeBinding, kind:"system", step:"screenings", condition:"APR intende usare un documento tecnico come fonte dei prodotti di una pratica Infissi", sourcePrecedence:["identita cliente/cantiere attesa e presente sia nel documento tecnico sia nella fattura", "riferimento ordine/commessa esplicito in entrambe le catene documentali", "firma completa di quantita e misure identica a una sola commessa fatturata"], deterministicAction:"Accettare il documento tecnico soltanto quando cliente/cantiere, catena ordine/commessa e firma completa dei prodotti lo collegano in modo univoco alle fatture della stessa pratica. Riferimenti assenti, piu ordini compatibili, firme parziali o prodotti incompatibili chiudono il gate senza scegliere per somiglianza.", audit:"practiceId, cliente atteso, sourceId tecnico, sourceId fatture abbinate, riferimenti ordine/commessa, firme prodotto, tre esiti di collegamento, blocker e ID regola", outcome:"requested_operator", provenance:USER_RULE_PROVENANCE_2026_09_03,
    lifecycle: {
      status: "superseded",
      generalGateEligible: false,
      supersededByRuleId: USER_AUTHORIZED_RULE_IDS.technicalDocumentPracticeBindingProductSignatureOnly,
      note: "Correzione di Giuliano (Cappello, 2026-09-07): richiedere identita cliente/rivenditore o riferimento ordine/commessa nel documento tecnico del produttore falliva sempre per costruzione, perche' quel documento riporta di norma solo il costruttore e un riferimento di fornitura interno del produttore, mai il rivenditore ne' il cliente finale. Sostituita da una verifica che usa esclusivamente la misura dichiarata in fattura, quando presente.",
    },
  },
  { id:USER_AUTHORIZED_RULE_IDS.technicalDocumentPracticeBindingProductSignatureOnly, kind:"business", step:"screenings", condition:"Regola generale di Giuliano: APR intende usare un documento tecnico di terzi (DoP, dichiarazione di conformita' o di prestazione) come fonte dei prodotti Infissi di una pratica. Quei documenti riportano per costruzione il nome del costruttore e un riferimento di fornitura interno al costruttore, mai il rivenditore ne' il cliente finale: la loro assenza e' normale, non un segnale di anomalia.", sourcePrecedence:["misura L x H dichiarata esplicitamente in fattura per lo stesso prodotto, quando presente", "in assenza di una misura dichiarata in fattura, il documento tecnico allegato dal rivenditore alla pratica e' considerato valido di default"], deterministicAction:"Non cercare mai una corrispondenza per nome cliente/rivenditore o per numero d'ordine/commessa tra il documento tecnico e la fattura: quel confronto fallisce sempre per costruzione su questo tipo di documento e non prova nulla. Accettare il documento tecnico allegato alla pratica di default. Bloccare fail-closed soltanto quando la fattura dichiara essa stessa, esplicitamente, una misura L x H diversa da quella del documento tecnico: quello e' l'unico segnale residuo di un vero conflitto documentale.", audit:"practiceId, sourceId tecnico selezionato, misura dichiarata in fattura (se presente), misura del documento tecnico, esito del confronto e ID regola.", outcome:"requested_operator", priority:1308, provenance:USER_RULE_PROVENANCE_2026_09_07 },
  { id:"system-multipage-bank-receipt-label-reconciliation-v1", kind:"system", step:"gross_reconciliation", condition:"Un allegato bancario multipagina contiene piu bonifici con etichette Importo, Commissioni, Totale operazione, credito/debito o TRN disposte in colonne o righe OCR sfalsate", sourcePrecedence:["confini pagina persistiti", "TRN/CRO univoco anche su riga successiva", "riferimento fattura esplicito", "terna capitale+commissioni=addebito o importo credito/debito ripetuto univocamente"], deterministicAction:"Segmentare una ricevuta per pagina, associare i valori soltanto alle etichette bancarie e accettare il capitale quando la terna aritmetica o il prospetto credito/debito e univoco. Deduplicare prima per TRN; riferimenti o importi ambigui restano null e fanno fallire chiuso la riconciliazione.", audit:"documentKey, indice pagina, TRN/CRO, riferimento fattura, capitale, commissioni, addebito, prova aritmetica, candidati scartati e ID regola", outcome:"continue" },
  { id:"system-label-anchored-invoice-totals-v1", kind:"system", step:"gross_reconciliation", condition:"Una fattura espone piu importi in tabelle o riepiloghi, inclusi totale IVA, totale ordine e totale documento", sourcePrecedence:["valore ancorato a totale documento/importo totale/netto a pagare/totale dovuto", "nessun fallback da altre cifre"], deterministicAction:"Leggere esclusivamente il totale finale esplicitamente etichettato. Ignorare TOTALE IVA, imponibile, aliquote, totale ordine, scadenziari, somme riga e bonifici ai fini della lettura e validazione del totale fattura; ambiguita del totale finale resta fail-closed.", audit:"etichetta finale, valore associato, riga/pagina, candidati intermedi ignorati e ID regola", outcome:"continue" },
  { id:"system-sdi-pa-digitale-fiscal-summary-v1", kind:"system", step:"economic_sources", condition:"La rappresentazione di una fattura elettronica SdI/PA-Digitale separa dati generali e totale documento", sourcePrecedence:["Dati Generali Documento per numero e data", "Importo Totale Documento/Pagamento etichettato"], deterministicAction:"Interpretare le sezioni SdI come un unico documento fiscale e collegare numero/data al solo totale finale. Non leggere riepiloghi IVA o imponibili; sezioni incomplete o piu totali finali incompatibili restano fail-closed.", audit:"formato SdI, numero/data, totale finale, associazioni rifiutate e ID regola", outcome:"continue" },
  { id:"system-apr-chrome-keepalive-immortal-v1", kind:"system", step:"runner_lifecycle", condition:"Qualunque quiescenza, arresto, timeout, finalizzazione o STOP operatore termina servizi APR", sourcePrecedence:["identita del processo Chrome principale vincolata alla receipt", "policy centrale dei soli ruoli arrestabili supervisor/worker/watchdog", "processo Chrome detached e unref dal worker"], deterministicAction:"Rendere il processo Chrome APR/ENEA non arrestabile dal software operativo. Ogni bootout deve accettare soltanto label di coorte tipizzate e ogni segnale deve accettare soltanto un PID il cui comando effettivo appartiene a supervisor, worker o watchdog. Rifiutare sempre Chrome/CDP fail-closed. Lo stop del runtime chiude soltanto i client CDP; Chrome resta detached, vivo e riutilizzabile dalla coorte successiva.", audit:"rule ID, label o PID richiesto, comando effettivo, ruolo ammesso/rifiutato, receipt Chrome, detach/unref, client CDP chiusi e processo Chrome osservato vivo", outcome:"continue" },
  { id:"system-global-enea-browser-controller-fenced-lease-v2", kind:"system", step:"runner_lifecycle", condition:"Qualunque processo APR intende osservare o pilotare il Chrome ENEA condiviso", sourcePrecedence:["lock persistente legato allo user-data-dir canonico e alla porta", "fencing epoch e token correnti", "lease non scaduta", "capability read-only o mutating richiesta dal driver"], deterministicAction:"Richiedere una capability obbligatoria nel costruttore del driver. Separare accesso read-only e mutating, verificare token, epoch, PID e scadenza durante tutta l'operazione e prima di ogni comando CDP. Rinnovare la lease esclusivamente al confine di un nuovo comando, mai dal polling di fencing o mentre un comando e in corso: un holder vivo ma bloccato deve scadere ed essere reso tecnicamente incapace di continuare. Conservare la lease per l'intera pratica e rilasciarla durante idle o attese tra pratiche; eseguire il keepalive con capability read-only separata.", audit:"profile realpath, porta, ownerId, PID, capability, token fingerprint, fencing epoch, acquiredAt, leaseUntil, rinnovo al confine comando, assert durante comando, rilascio, recupero e ID regola", outcome:"continue" },
  { id:"system-global-browser-lock-atomic-publication-v1", kind:"system", step:"runner_lifecycle", condition:"Due o piu processi APR contendono la creazione esclusiva del lock globale Chrome/ENEA", sourcePrecedence:["inode temporaneo completo e fsync nello stesso filesystem", "pubblicazione atomica mediante hard link esclusivo", "EEXIST del lock gia pubblicato", "lock pubblicato malformato sempre fail-closed"], deterministicAction:"Serializzare il JSON completo in un file temporaneo univoco, eseguire fsync e close prima di renderlo visibile come lock, quindi pubblicare l'inode con hard link atomico nello stesso directory. Se il target esiste, non sostituirlo e restituire contesa; sincronizzare il directory e rimuovere sempre il temporaneo. Non cancellare, tollerare o reinterpretare come transitorio un lock target malformato.", audit:"lock path, temporary path, ownerId, PID, token fingerprint, fencing epoch, esito link/EEXIST, fsync file/directory, cleanup temporaneo e ID regola", outcome:"continue" },
  { id:"system-sequencer-recovery-queued-server-proof-v1", kind:"system", step:"runner_lifecycle", condition:"Il sequencer incontra una pratica recovery_queued prima del bootstrap del worker", sourcePrecedence:["GET canonica autenticata della stessa bozza con persisted_fields_get=not_saved", "checkpoint della stessa pagina con primo Salva gia tentato", "evidence ID server persistito e concordante", "budget di recupero residuo esattamente pari a uno"], deterministicAction:"Ammettere recovery_queued al preflight esclusivamente se l'esecuzione e ready, la prova server not_saved e unica e riferita alla stessa bozza, una sola pagina e autorizzata con lo stesso evidence ID, saveAttemptCount e uno e recoverySaveAttemptCount e zero. Qualunque assenza, discordanza, altra autorizzazione o budget diverso da uno produce un errore tecnico fail-closed prima del bootstrap; non attendere e non eseguire Salva.", audit:"customerKey, draftId, pageId, stato esecuzione, metodo/esito/URL/evidenceId della prova server, saveAttemptCount, recoverySaveAttemptCount, budget residuo, numero pagine autorizzate, verdetto e ID regola", outcome:"continue" },
  { id:"system-worker-recovery-queued-continuation-v1", kind:"system", step:"runner_lifecycle", condition:"La sonda read-only del worker ha gia trasformato atomicamente un Salva incerto in recovery_queued con prova persisted_fields_get=not_saved sulla stessa bozza e budget residuo uno", sourcePrecedence:["checkpoint transazionale recovery_queued", "prova GET canonica persisted_fields_get=not_saved", "evidence ID di autorizzazione sulla stessa pagina", "budget di recupero residuo uno"], deterministicAction:"Registrare l'autorizzazione come action_completed e lasciare che il ciclo successivo reclami la medesima pratica per l'unico Salva di recupero. Non eseguire il ramo generico case_isolated dopo una recovery_authorized valida. Prove inconclusive, URL non canonico, evidence discordanti o budget diverso restano operator_required fail-closed.", audit:"customerKey, draftId, pageId, stato recovery_queued, metodo/esito/URL/evidenceId, contatori Salva e recupero, evento worker, verdetto e ID regola", outcome:"continue" },
  { id:"system-sequencer-uncertain-save-probe-lifecycle-v1", kind:"system", step:"runner_lifecycle", condition:"Un Salva incerto e persistito come probing oppure recovery_queued mentre il worker deve ancora completare le sonde read-only o reclamare la stessa bozza", sourcePrecedence:["checkpoint transazionale della stessa bozza e pagina", "stato uncertainty probing/recovery_authorized/resolved_saved", "insieme univoco delle sonde persistite", "prova server e budget di recupero quando applicabili", "autorizzazione, coorte e draftId del risultato sequencer persistito"], deterministicAction:"Trattare probing e recovery_queued come stati transitori non terminali. Un worker riavviato riprende soltanto le sonde read-only mancanti; il sequencer attende e non spegne il worker. Un vecchio INCONSISTENT del sequencer viene ritirato soltanto se autorizzazione, coorte, customerKey e draftId coincidono con lo stato transitorio autorevole; risultati terminali, bozze diverse e autorizzazioni diverse restano intatti. Recovery_queued viene reclamato sulla stessa bozza soltanto con prove e budget validi. Stati incoerenti producono INCONSISTENT fail-closed e nessun Salva alla cieca.", audit:"customerKey, draftId, pageId, stato item/esecuzione/uncertainty, metodi sonda gia persistiti e mancanti, evidence ID, budget, identita worker, risultato sequencer ritirato con autorizzazione/coorte/bozza, verdetto sequencer e ID regola", outcome:"continue" },
  { id:"system-screening-fresh-proof-before-terminal-v1", kind:"system", step:"runner_lifecycle", condition:"Il worker raccoglie una GET canonica del riepilogo tecnico mentre una riga annidata ha un Salva incerto e la fotografia di inizio ciclo contiene meno di due prove", sourcePrecedence:["checkpoint fresco del driver dopo la GET appena conclusa", "due GET canoniche indipendenti e concordanti", "checkpoint transazionale della stessa bozza", "budget di recupero ancora integro"], deterministicAction:"Dopo ogni GET canonica appena persistita chiudere il ciclo senza consumare altre sonde e senza pubblicare un terminale. Nel ciclo successivo rileggere il checkpoint fresco: con due prove conclusive applicare il recupero 1:1 gia previsto sulla stessa bozza; con prove incomplete o discordanti restare fail-closed. Non emettere alcun Salva durante la raccolta delle prove.", audit:"customerKey, draftId, pagina incerta, numero prove prima e dopo la GET, evidence ID distinti, esito concordanza, decisione defer/recover/fail-closed e ID regola", outcome:"continue" },
  { id:"system-sequencer-screening-canonical-absence-resume-v1", kind:"system", step:"runner_lifecycle", condition:"Il sequencer incontra un vecchio terminale operator_required su una riga Infissi mentre il checkpoint transazionale conserva budget integro e il driver contiene due GET canoniche indipendenti della stessa bozza che mostrano zero righe persistite", sourcePrecedence:["due GET canoniche autenticate della stessa bozza con evidence ID distinti", "checkpoint persistente delle righe annidate", "riepilogo esterno ancora mai salvato", "budget di recupero non consumato"], deterministicAction:"Riclassificare il terminale precedente come transitorio e riavviare il worker sulla stessa bozza. Il worker rivaluta le due prove e applica il recupero deterministico gia registrato; senza identita esatta, due prove conclusive o budget integro mantenere operator_required fail-closed. Il sequencer non esegue click ne salvataggi.", audit:"authorizationId, customerKey, cohort, draftId, evidence ID delle due GET, struttura checkpoint, contatori primari/recupero, risultato ritirato, decisione resume/fail-closed e ID regola", outcome:"continue" },
  { id:"system-sequencer-screening-recovery-filling-lifecycle-v1", kind:"system", step:"runner_lifecycle", condition:"Il recupero Infissi autorizzato da due GET canoniche ha gia trasformato le righe in pending sulla stessa bozza e lo stato persistente e filling prima che il worker consumi i tentativi di recupero", sourcePrecedence:["checkpoint running con currentCustomerKey coincidente", "due GET canoniche della stessa bozza", "recoveryAuthorizedEvidenceId coincidente sulle sole righe gia tentate: seconda GET canonica oppure prova persisted_fields_get a zero campi collegata all'audit di recupero del prefisso parziale", "contatori recovery ancora a zero"], deterministicAction:"Trattare filling con recovery_authorized come transitorio e lasciare attivo o riavviare il worker. Ritirare soltanto il technical_block storico generato dall'esatto mismatch di questo stato; qualunque identita, prova, audit, struttura o budget discordante resta fail-closed. Il sequencer non emette mutazioni.", audit:"authorizationId, customerKey, cohort, draftId, stato execution, currentCustomerKey, due evidence ID canonici, eventuale persisted_fields_get a zero campi e relativo commandId di recupero, righe gia tentate/intatte, contatori recovery, technicalReason ritirato e ID regola", outcome:"continue" },
  { id:"system-sequencer-recovery-prepared-window-lifecycle-v1", kind:"system", step:"runner_lifecycle", condition:"Dopo una GET canonica persisted_fields_get=not_saved e il claim dell'unico recupero, il worker ha preparato e verificato la pagina sulla stessa bozza ma non ha ancora registrato l'intento mutativo del recupero", sourcePrecedence:["checkpoint running e currentCustomerKey coincidente", "unica GET canonica not_saved della stessa bozza persistita nei serverEvidenceIds", "unica pagina con recoveryAuthorizedEvidenceId coincidente", "stato pagina prepared con preparedEvidenceId e nessuna prova saved", "saveAttemptCount uno e recoverySaveAttemptCount zero"], deterministicAction:"Considerare esclusivamente questa finestra prepared come transitoria e attendere il worker senza emettere un verdetto o una mutazione. Il successivo intento puo consumare l'unico recupero gia autorizzato; bozza, prova, pagina, contatori o preparedEvidenceId mancanti o discordanti restano fail-closed.", audit:"customerKey, draftId, pageId, stato item/pagina, evidenceId not_saved e prepared, saveAttemptCount, recoverySaveAttemptCount, numero pagine autorizzate, verdetto e ID regola", outcome:"continue" },
  { id:"system-cdp-readonly-same-origin-navigation-v1", kind:"system", step:"runner_lifecycle", condition:"APR deve verificare o mantenere la sessione ENEA con una capability esclusivamente read-only e la pagina corrente non espone ancora un verdetto autenticato", sourcePrecedence:["capability read-only valida e non fenced", "origine ENEA allowlist esatta", "URL HTTPS privo di credenziali", "loopback HTTP ammesso soltanto nelle fixture locali", "navigazione GET del browser senza input, click o submit"], deterministicAction:"Consentire alla capability read-only soltanto Page.navigate verso un URL HTTPS della stessa origine ENEA allowlist, tramite un wrapper dedicato non riutilizzabile per navigazioni generiche. Tutti i percorsi di lifecycle del keepalive (normalizzazione origine, verifica sessione e inventario contratto) devono usare esclusivamente tale wrapper anche quando la scheda corrente e una pratica e occorre tornare alla dashboard. HTTP e ammesso esclusivamente per le origini loopback esatte 127.0.0.1, localhost o ::1 usate dai test locali. Ogni origine diversa, host remoto non HTTPS, credenziale nell'URL o uso del metodo navigate generico resta mutating e viene rifiutato fail-closed prima di aprire il WebSocket.", audit:"ownerId, fencing epoch, capability kind, URL richiesto, origine allowlist, protocollo, eventuale identita loopback, esito guardia, metodo CDP e ID regola", outcome:"continue" },
  { id:"system-chrome-instance-identity-receipt-v1", kind:"system", step:"runner_lifecycle", condition:"APR avvia o si riaggancia a un endpoint Chrome CDP locale", sourcePrecedence:["receipt persistente dell'istanza avviata da APR", "PID e start time del processo Chrome principale", "comando effettivo con user-data-dir canonico e porta", "nonce dell'istanza"], deterministicAction:"Non fidarsi della sola risposta sulla porta. Accettare Chrome soltanto se receipt, realpath del profilo, porta, PID/start time, eseguibile, comando effettivo e nonce concordano; in caso di discordanza o receipt assente rifiutare fail-closed. Prima del passaggio a una nuova coorte richiedere inoltre assenza verificata di client CDP residui del precedente owner.", audit:"receipt versionata, nonce, PID, start time, command fingerprint, realpath profilo, porta, target osservati, client residui e verdetto", outcome:"continue" },
  { id:"system-cdp-explicit-operation-timeouts-v1", kind:"system", step:"runner_lifecycle", condition:"Il driver esegue JavaScript nella pagina tramite Runtime.evaluate", sourcePrecedence:["classe tipizzata dichiarata dal chiamante", "un solo campo React per comando mutativo durante la compilazione form", "massima attesa in-page dichiarata e margine della classe", "massimo globale fail-closed"], deterministicAction:"Vietare evaluate con timeout implicito. Usare esclusivamente wrapper DOM_READ, SHORT_MUTATION, NESTED_SAVE o SERVER_RECONCILIATION: DOM_READ non puo contenere cicli async o mutazioni; la compilazione di un form deve spezzare i campi React in comandi distinti e verificarli con una lettura separata; ogni altra classe deve garantire la massima attesa in-page piu un margine esplicito. Rifiutare override non valido o oltre il massimo e rendere rumoroso ogni timeout. Dopo un timeout successivo a un click non assumere mai il fallimento e consentire soltanto riconciliazione read-only prima di qualsiasi nuovo intento mutativo.", audit:"metodo, classe, campo, limite, attesa in-page, margine, durata, eventuale terminateExecution, fase prima/dopo click, riconciliazione e verdetto", outcome:"continue" },
  { id:"system-cdp-react-remount-readonly-poll-v1", kind:"system", step:"runner_lifecycle", condition:"APR attende che marker o valori DOM compaiano durante il caricamento o il remount di una pagina React ENEA", sourcePrecedence:["probe DOM_READ sincrona e senza awaitPromise", "polling temporizzato nel processo Node", "numero massimo di tentativi dichiarato", "errore CDP tipizzato con classe e fingerprint"], deterministicAction:"Non mantenere mai nel renderer una Promise asincrona di sola lettura durante l'attesa dei marker React. Eseguire dal processo Node una sequenza limitata di probe DOM_READ sincrone e indipendenti, ciascuna con awaitPromise=false. Se la condizione non compare terminare fail-closed senza click, salvataggi o retry mutativi. Se CDP restituisce un errore di protocollo conservarne codice e messaggio e aggiungere classe, modalita awaitPromise e fingerprint dell'espressione.", audit:"customerKey, draftId, pageId, numero probe, intervallo, classe DOM_READ, awaitPromise, errore protocollo, expression fingerprint, esito e ID regola", outcome:"continue" },
  { id:"system-cdp-authoritative-get-deadline-v1", kind:"system", step:"runner_lifecycle", condition:"Una preparazione form mutativa usa una GET autenticata autorevole eseguita dentro Runtime.evaluate", sourcePrecedence:["deadline in-page inferiore al limite SHORT_MUTATION", "AbortController condiviso dall'intera sequenza GET", "fallback DOM fisico gia osservato"], deterministicAction:"Applicare una deadline totale di quindici secondi alla sequenza GET autorevole dei Comuni, cancellare la fetch con AbortController e restituire esito non risolto al percorso di fallback senza lasciare Runtime.evaluate appesa fino al timeout CDP. Il timeout CDP deve includere classe, durata ed espression fingerprint nell'errore rumoroso.", audit:"customerKey, pageId, portalId, endpoint same-origin, deadline, response status, AbortError/fetch error, classe timeout, expression fingerprint e percorso fallback", outcome:"continue" },
  { id:"system-nested-page-transaction-v1", kind:"system", step:"checkpoint_persistence", condition:"Una pratica contiene una pagina annidata che deve essere confermata e poi persistita dal salvataggio esterno", sourcePrecedence:["checkpoint transazionale persistente", "stato DOM annidato osservato", "prova server riletta dopo il salvataggio esterno"], deterministicAction:"Applicare a tutte le pagine annidate una macchina a stati unica: nested_prepared, nested_staged_verified, outer_save_intent persistito prima del click, ambiguous_after_click se manca una risposta conclusiva, server_reconciled e saved oppure operator_required. Dopo un timeout eseguire solo riconciliazione read-only; un nuovo click e ammesso soltanto con prova concordante che il precedente non abbia persistito.", audit:"practiceId, pageKey, transactionId, stato precedente/nuovo, intentId, evidenceId DOM/server, timeout, riconciliazione, contatore click e ID regola", outcome:"continue" },
  { id:"system-enea-save-material-delivery-proof-v1", kind:"system", step:"checkpoint_persistence", condition:"Dopo l'unico intento Salva ENEA il browser osserva richieste di rete, eventi DOM o cambi di rotta e deve stabilire se l'intento e stato materialmente consegnato all'applicazione", sourcePrecedence:["mutazione POST/PUT/PATCH sull'endpoint esatto /api/pratica/ecobonus/2026/tmp/{canonicalDraftId}", "cambio di rotta dalla pagina sorgente", "per una pagina annidata, comparsa della riga tecnica attesa", "POST opachi di telemetria o anti-bot esclusi"], deterministicAction:"Considerare consegnato l'unico intento soltanto con una prova materiale riferita alla stessa bozza o, per la pagina annidata, con la riga attesa visibile. Un POST opaco non consuma la catena di consegna: APR puo completare il medesimo intento gia journaled con la sequenza limitata puntatore, Invio e click React. Se nessuna prova materiale compare, chiudere fail-closed senza creare un secondo intento o una nuova bozza.", audit:"customerKey, canonicalDraftId, pageKey, intentId, richieste classificate business/telemetria, rotta prima/dopo, riga annidata attesa, fallback usato, esito e ID regola", outcome:"continue" },
  { id:"system-calculation-allocation-single-intent-delivery-v1", kind:"system", step:"checkpoint_persistence", condition:"Il modale React di allocazione costi conserva il valore preparato ma il click fisico non raggiunge form.onSubmit", sourcePrecedence:["modale 36% ancora aperto dopo attesa limitata", "tabella riepilogo ancora sul valore precedente", "zero richieste mutative osservate", "unico intento Salva gia journaled", "form React con onSubmit e unico controllo submit Salva valido e abilitato"], deterministicAction:"Completare lo stesso intento mediante requestSubmit senza submitter sul solo form React univoco, esclusivamente quando modale aperto, tabella immutata e zero richieste mutative provano congiuntamente la mancata consegna. Il canale tastiera collaudato resta disponibile soltanto per superfici non-React. Se il modale e chiuso, la tabella e aggiornata, esiste traffico mutativo, il form/controllo non e unico o il valore non e verificato, non ridistribuire l'intento e terminare fail-closed.", audit:"customerKey, canonicalDraftId, pageKey, intentId, modalOpen, allocationTableMatched, mutationTraceCount, contratto form.onSubmit, controllo submit univoco, canale di consegna, esito e ID regola", outcome:"continue" },
  { id:"system-calculation-allocation-post-outer-canonical-proof-v1", kind:"system", step:"checkpoint_persistence", condition:"L'allocazione costi e una pagina annidata staged che deve essere provata dopo il Salva esterno della pagina Calcolo", sourcePrecedence:["checkpoint staged dell'allocazione", "unico intento Salva esterno completato", "GET canonica allowlist /calcolo della stessa bozza", "tabella autorevole con aliquota e totale attesi"], deterministicAction:"Dopo il Salva esterno navigare esclusivamente in GET alla pagina Calcolo della stessa bozza e riusare il classificatore deterministico della tabella allocazione. Promuovere l'allocazione a saved soltanto se aliquota 50%, aliquota 36% e totale coincidono con i valori attesi; qualunque altra pagina annidata non esplicitamente allowlist resta rifiutata fail-closed.", audit:"customerKey, canonicalDraftId, outerPageId, nestedPageId, route GET, valori 50/36/totale, evidenceId e ID regola", outcome:"continue" },
  { id:"system-final-draft-durable-canonical-proof-v1", kind:"system", step:"checkpoint_persistence", condition:"Tutte le pagine della bozza possiedono un unico Salva e una verifica server autorevole, ma il portale conserva la pagina finale sulla rotta canonica /calcolo invece di redirigere a /riepilogo", sourcePrecedence:["catena completa di prove per-pagina sulla stessa bozza", "prova server JSON annidata distinta e positiva per il generatore", "GET canonica /calcolo della stessa bozza con campi finali verificati", "assenza di qualunque prova rejected nella catena accettata"], deterministicAction:"Certificare la bozza senza ripetere mutazioni soltanto quando ogni pagina attesa ha Salva e prova successiva valide e la prova finale e una verifica read-only sulla rotta esatta /calcolo/{canonicalDraftId} oppure il redirect storico esatto /riepilogo/{canonicalDraftId}. Registrare azioni diverse per sonde annidate positive e rifiutate; una sonda rifiutata, una rotta diversa o una pagina priva di prova chiudono il gate fail-closed.", audit:"customerKey, canonicalDraftId, pageIds attesi, coppie Salva/prova, azione positiva o rejected della sonda annidata, rotta finale, evidenceId e ID regola", outcome:"continue" },
  { id:"system-nested-server-envelope-proof-v1", kind:"system", step:"checkpoint_persistence", condition:"Il PUT dell'outer page risponde 200 ma la GET JSON fresca non espone un sottoalbero annidato riconoscibile", sourcePrecedence:["corpo breve della GET autenticata senza cache", "schema e chiavi dell'envelope JSON", "hash del corpo e match dei valori attesi", "DOM escluso come prova server"], deterministicAction:"Non equiparare HTTP 200 a persistenza e non equiparare l'assenza di candidatePaths a mancata persistenza finche l'envelope non e classificato. Conservare integralmente soltanto risposte fino a 4096 byte; per payload piu lunghi conservare hash, schema e chiavi senza dati personali. Eseguire la diagnostica soltanto con capability read-only fenced e nessun click. Distinguere payload draft, wrapper ID, errore applicativo e risposta non JSON prima di correggere il writer o il verificatore.", audit:"customerKey, draftId, pageId, GET path, content-type, lunghezza, SHA-256, topLevelKeys, resultKeys, error/status envelope, corpo breve o flag redatto, candidatePaths, matchedPath, capability e ID regola", outcome:"continue" },
  { id:"system-screening-staged-server-rounding-v1", kind:"system", step:"checkpoint_persistence", condition:"La riga schermatura riletta dal riepilogo ENEA espone la superficie prodotto arrotondata a due decimali mentre il payload documentato conserva fino a quattro decimali", sourcePrecedence:["riga server riletta dopo il Salva", "payload tecnico documentato ad alta precisione", "precisione di visualizzazione ENEA a due decimali", "classificatore condiviso delle righe schermatura"], deterministicAction:"Usare lo stesso classificatore condiviso sia nella verifica immediata post-Salva sia nell'integrita finale. Per la sola superficie schermatura accettare il normale arrotondamento server a due decimali entro 0,0051 m2; mantenere rigorosi gli altri campi e rifiutare differenze maggiori. Non classificare come ambiguo un Salva quando la riga server e presente e differisce soltanto per tale arrotondamento.", audit:"customerKey, draftId, pageId, indice riga, superficie payload, superficie server, delta, tolleranza, campi restanti, evidenceId e ID regola", outcome:"continue" },
  { id:"system-terminal-observability-snapshot-v1", kind:"system", step:"checkpoint_persistence", condition:"APR pubblica lo stato di una coorte attiva o terminale", sourcePrecedence:["checkpoint pratica", "report.blockers persistenti con stato blocked_case", "evidenza tecnica driver-error tipizzata per un errore circoscritto", "snapshot API atomico e versionato"], deterministicAction:"Produrre uno snapshot terminale atomico e versionato prima della quiescenza, includervi la verita caso e conservarlo in un endpoint indipendente dal worker della coorte. Un blocked_preflight e terminale e OPERATOR_REQUIRED soltanto se il preflight completato contiene blocked_case e almeno un report.blockers coerente. Un errore driver tipizzato privo di blocker operatore resta un TECHNICAL_BLOCK esplicito, non viene convertito in OPERATOR_REQUIRED; senza blocker o prova tecnica pubblicare esclusivamente INCONSISTENT. L'osservatore indipendente deve servire /api/case-truth dallo snapshot anche dopo la quiescenza. Dopo il finalizzatore, sia dashboard/status.json sia l'HTML statico sia /api/status devono derivare dallo stesso snapshot sequencer_finalizer; lo stato worker quiescente resta solo evidenza legacy e non puo riscrivere il verdetto terminale.", audit:"runId, cohortId, snapshot version/revision, source fingerprints, stato, current case, stato preflight, report.blockers, driver-error evidenceId, case-truth, observedAt, statusSource del JSON statico, titolo HTML e stato endpoint", outcome:"continue" },
  { id:"system-terminal-observability-live-source-supersession-v1", kind:"system", step:"checkpoint_persistence", condition:"Esiste uno snapshot terminale immutabile ma sono disponibili checkpoint execution o worker correnti", sourcePrecedence:["revision e sourceFingerprint del checkpoint execution corrente", "revision e instanceId del worker corrente", "revision e fingerprint catturati dal finalizzatore", "snapshot terminale conservato come storia"], deterministicAction:"Mostrare lo snapshot terminale come verita corrente soltanto quando ogni fonte live disponibile coincide esattamente per revisione e identita con le fonti catturate dal finalizzatore. Se una fonte e successiva o discordante, conservare lo snapshot nell'endpoint storico ma derivare lo stato corrente dalle fonti live; se execution e worker non concordano, pubblicare esclusivamente INCONSISTENT e nessun verdetto della pratica.", audit:"snapshotId, revision/fingerprint terminali, revision/fingerprint live, esito corrispondenza, stato dashboard, case-truth e ID regola", outcome:"continue" },
  { id:"system-terminal-ambiguous-save-evidence-v1", kind:"system", step:"checkpoint_persistence", condition:"Una pratica termina con esito tecnico incerto dopo un click Salva e senza blocker operatore", sourcePrecedence:["checkpoint con stato operator_intervention e motivo canonico nessun retry", "evidence ID uncertain-page tipizzato", "evidence ID probe-error tipizzato della riconciliazione read-only", "report.blockers vuoto"], deterministicAction:"Pubblicare TECHNICAL_BLOCK coerente soltanto quando entrambe le prove tipizzate sono persistite, il motivo canonico identifica il Salva ambiguo e report.blockers e vuoto. Se manca una prova pubblicare INCONSISTENT; se esiste un blocker operatore coerente pubblicare OPERATOR_REQUIRED. Non trasformare mai l'ambiguita in fallimento e non ripetere il click.", audit:"customerKey, pageId, stato checkpoint, motivo, uncertain-page evidenceId, probe-error evidenceId, report.blockers, snapshotId, case-truth e ID regola", outcome:"continue" },
  { id:"system-sequencer-progress-watchdog-v1", kind:"system", step:"runner_lifecycle", condition:"Il sequencer attende il completamento operativo di una pratica", sourcePrecedence:["checkpoint esecuzione e sue transizioni materiali", "stato processo worker", "stato sessione login_required o technical_block"], deterministicAction:"Non attendere mai un timeout fisso di due ore. Se login_required o il checkpoint non compie progresso materiale per cinque minuti, classificare il fatto come difetto tecnico comune verificato e arrestare il lotto senza produrre OPERATOR_REQUIRED sulla pratica. Un avanzamento reale azzera la finestra; il limite assoluto resta un fail-safe tecnico comune.", audit:"customerKey, fingerprint progresso iniziale/finale, worker PID/stato, session state, candidateSince, progressAgeMs, soglia, failure code e snapshot terminale", outcome:"continue" },
  { id:"system-sequencer-manifest-contract-v1", kind:"system", step:"runner_lifecycle", condition:"Un sequencer APR sta per avviare un test mirato o una coorte", sourcePrecedence:["manifest immutabile congelato", "insieme identita e cardinalita", "allowedStages ed esclusioni esplicite", "autorizzazione utente gia auditata"], deterministicAction:"Validare prima di qualunque quiescenza o avvio che cases, total, customerKey univoci, allowedStages ed excludedCustomerKeys esistano e concordino. Un campo mancante produce un errore tecnico tipizzato e zero pratiche processate; nessun accesso a proprieta undefined e nessun avvio parziale sono ammessi.", audit:"manifest SHA-256, authorizationId, total atteso/osservato, allowedStages, excludedCustomerKeys, customerKey, stage, verdetto e ID regola", outcome:"continue" },
  { id:"system-global-enea-browser-controller", kind:"system", step:"runner_lifecycle", condition:"Una o piu coorti APR condividono lo stesso profilo Chrome e la stessa sessione ENEA", sourcePrecedence:["lock globale legato all'identita effettiva del processo Chrome", "checkpoint globale del keepalive", "checkpoint della singola coorte"], deterministicAction:"Prima di ogni test spegnere e verificare assenti tutte le vecchie coorti; rifiutare l'avvio se un servizio o processo resiste. Consentire a un solo processo alla volta di usare Chrome/ENEA con una lease che copre l'intera pratica, non il singolo tick; coordinare un solo keepalive globale. Rispettare il timeout tipizzato richiesto dal chiamante entro il massimo globale di trenta secondi e, quando una Runtime.evaluate scade, inviare Runtime.terminateExecution prima di chiudere il WebSocket. Pubblicare il verdetto soltanto dopo la quiescenza reale del worker e due letture stabili concordanti. Un lock vivo non puo essere scavalcato; un lock corrotto resta fail-closed; un lock stale e recuperabile soltanto con prova che il PID proprietario non esiste piu.", audit:"servizi e PID preesistenti, ownerId, PID/start time/comando/nonce Chrome, profilo realpath, porta CDP, scopo e durata lease, acquisizione/rilascio, recupero stale, classe/margine timeout, terminateExecution, letture finali stabili, keepalive evidenceId, revisione e timestamp", outcome:"continue" },
  { id:"system-screening-primary-measurements-operator-routing", kind:"system", step:"screenings", condition:"La fattura originaria identifica una schermatura fisica ma fattura e form originario non riportano alcuna misura del prodotto", sourcePrecedence:["misure prodotto esplicite nella fattura originaria", "campo Dimensioni prodotto del form originario", "misure finestra protetta escluse come prova delle misure prodotto"], deterministicAction:"Non inventare larghezza, altezza o superficie e non usare le dimensioni della finestra protetta come sostituto. Classificare Richiesto intervento operatore con la domanda precisa di acquisire o confermare le misure fisiche del prodotto; dopo la risposta auditata rimettere la pratica in Pronte da fare.", audit:"practiceId, sourceIds, descrizione prodotto, ricerca misure in fattura e form, eventuali sole misure finestra protetta, blocker stabile, domanda operatore e ID regola", outcome:"requested_operator" },
  { id:"system-composite-invoice-bank-transfer-page-segmentation", kind:"system", step:"economic_sources", condition:"Un unico allegato multipagina contiene sia una fattura o nota di credito sia una o piu prove di bonifico", sourcePrecedence:["segmenti fiscali con marcatori propri della fattura", "segmenti bancari usati soltanto per riconciliazione", "allegato intero mai escluso per la sola presenza di un bonifico"], deterministicAction:"Segmentare sempre l'allegato. Conservare nel mapping tecnico ed economico soltanto i segmenti fattura/nota di credito con marcatori fiscali propri; conservare i bonifici esclusivamente nel controllo incrociato e non sommarli come fatture. Un segmento solo bancario resta escluso fail-closed.", audit:"documentKey, segmentId, tipo documento, marcatori fiscali, prove bancarie, inclusione/esclusione, campi derivati e ID regola", outcome:"continue" },
  { id:"system-draft-payload-mapping-completeness", kind:"system", step:"enea_mapping", condition:"Il preflight documentale non presenta blocker ma il costruttore del payload ENEA segnala dati o mapping incompleti", sourcePrecedence:["report preflight e fonti originarie", "esito strutturato del costruttore payload", "contratto portale versionato"], deterministicAction:"Non dichiarare READY e non accodare la pratica. Registrare un blocker tecnico di mapping con i campi mancanti, correggere il parser/mapping generale, testare e rieseguire dal checkpoint senza azioni esterne.", audit:"customerKey, blocker payload, campi mancanti, sourceIds, revisione parser/mapping, test, bundle e replay", outcome:"continue" },
  { id:"system-paper-form-birth-date-leading-digit-ocr-repair", kind:"system", step:"identity_property", condition:"Un modulo cartaceo originario contiene un CF valido e l'OCR perde la cifra iniziale 1 del giorno oppure legge la barra prima del mese come cifra 1", sourcePrecedence:["data visibile nel modulo cartaceo originario", "CF formalmente valido presente nello stesso modulo e nella fattura originaria", "nome e cognome concordanti"], deterministicAction:"Ricostruire esclusivamente la cifra iniziale 1 persa dal giorno oppure il separatore deformato nel formato D[D] 1MM YYYY quando anno, mese e giorno codificati dal CF concordano in modo univoco. Conservare testo osservato e valore normalizzato. In ogni altro caso non correggere e restare fail-closed.", audit:"sourceId modulo e fattura, data OCR, tipo deformazione, CF, segmenti data codificati, data ricostruita, esito e ID regola", outcome:"continue" },
  { id:"system-original-pratica-rapida-paper-form-explicit-values-v1", kind:"system", step:"identity_property", condition:"Un allegato originario contiene il modulo cartaceo standard PraticaRapida compilato, ma non e classificato come form strutturato CRM, oppure il form inline CRM contiene soltanto alcune sezioni", sourcePrecedence:["valori gia presenti nel form inline", "valori testuali espliciti del modulo cartaceo originario con identita concordante", "identita della riga CRM", "CF concordante nella fattura originaria"], deterministicAction:"Riconoscere il template standard indipendentemente dal rivenditore. Quando il form inline e parziale, completare ricorsivamente soltanto campi assenti o vuoti con valori testuali espliciti del modulo cartaceo concordante, senza sovrascrivere mai valori inline presenti. Moduli discordanti o piu moduli incompatibili restano fail-closed; crocette prive di prova posizionale e fallback impliciti specifici di rivenditore non vengono inventati.", audit:"documentKey, fingerprint template, campi inline presenti, campi completati dal cartaceo, valori espliciti, identita attesa, CF fattura, firme dei moduli, conflitti, warning e ID regola", outcome:"continue" },
  { id:"system-positioned-technical-order-products-v1", kind:"system", step:"screenings", condition:"Una scheda tecnica identifica la famiglia schermatura nell'intestazione e descrive i singoli prodotti in posizioni Pxx separate", sourcePrecedence:["famiglia prodotto esplicita nell'intestazione", "posizione Pxx", "quantita PZ, misure L/H e gTot tutti espliciti nella stessa posizione"], deterministicAction:"Creare righe fisiche soltanto per posizioni complete con quantita, L, H e gTot e normalizzare le misure entro i limiti autorizzati. Ogni posizione Pxx distinta resta un prodotto fisico anche quando due posizioni hanno misure identiche; una posizione incompleta non produce prodotti e resta fail-closed.", audit:"documentKey, posizione, famiglia, quantita, L/H originali e normalizzate, gTot e ID regola", outcome:"continue" },
  { id:"system-inline-description-product-measurements-v1", kind:"system", step:"screenings", condition:"Una fattura riporta famiglia prodotto e misura LxH sulla stessa riga descrittiva, mentre la quantita e isolata nelle righe immediatamente successive", sourcePrecedence:["riga descrittiva con famiglia schermatura e LxH", "quantita numerica isolata entro tre righe", "gTot locale esplicito"], deterministicAction:"Estrarre le righe fisiche soltanto quando i tre ancoraggi concordano; interpretare L/H come millimetri nel layout tecnico e deduplicare una riga equivalente gia estratta. Misure di vano generiche, quantita non isolata o gTot assente non producono un prodotto.", audit:"documentKey, riga descrittiva, L/H, distanza quantita, gTot, deduplica e ID regola", outcome:"continue" },
  { id:"system-tabular-equal-price-amount-single-quantity-v1", kind:"system", step:"screenings", condition:"Una rappresentazione tabellare SdI conserva descrizione, misure, prezzo unitario e importo di riga ma l'OCR omette la cella quantita", sourcePrecedence:["intestazioni PRODOTTI E SERVIZI/QUANTITA/PREZZO/IMPORTO", "descrizione schermatura con LxH", "prezzo unitario e importo riga consecutivi e identici al centesimo", "gTot esplicito"], deterministicAction:"Ricostruire esclusivamente quantita uno quando tutti gli ancoraggi concordano. Se prezzo e importo differiscono, una colonna manca, il gTot non e esplicito o esiste gia una riga equivalente, non ricostruire la quantita e restare fail-closed.", audit:"documentKey, intestazioni, descrizione, L/H, prezzo unitario, importo riga, gTot, esito uguaglianza e ID regola", outcome:"continue" },
  { id:"system-invoice-header-identity-over-body-reference", kind:"system", step:"gross_reconciliation", condition:"Il documento fiscale espone numero/data nell'intestazione e nel corpo cita una diversa fattura di acconto o saldo", sourcePrecedence:["intestazione fiscale numero/data", "riferimento acconto/saldo nel corpo"], deterministicAction:"Identificare il documento con numero e data dell'intestazione; conservare la fattura citata soltanto come riferimento. Deduplicare copie dello stesso numero/data/totale prima di contare righe tecniche e importi.", audit:"numero/data intestazione, riferimenti corpo, sourceId conservato/scartato e fingerprint tecnico", outcome:"continue" },
  { id:"system-explicit-replacement-invoice-supersession", kind:"system", step:"gross_reconciliation", condition:"Una fattura originaria dichiara esplicitamente di annullare e sostituire integralmente un'altra fattura identificata", sourcePrecedence:["dicitura esplicita annulla e sostituisce", "numero fattura sostitutiva", "numero fattura sostituita"], deterministicAction:"Escludere la fattura sostituita dal totale e dalle righe tecniche, usare una sola volta la fattura sostitutiva e conservare entrambe nell'audit. In assenza di dicitura o identificazione univoca non inferire la sostituzione.", audit:"sourceId e numero di entrambe le fatture, testo di sostituzione, totale incluso/escluso e timestamp", outcome:"continue" },
  { id:"system-apr-deep-review-before-operator", kind:"system", step:"runner_lifecycle", condition:"Un preflight locale produce uno o piu blocker prima dell'accesso al portale", sourcePrecedence:["dossier e documenti originari immutabili", "estrazione testo/OCR e struttura multipagina", "registro unico e precedenze gia autorizzate", "intervento operatore soltanto per prova mancante, conflitto esplicito o regola business assente"], deterministicAction:"Eseguire una seconda revisione persistente prima di classificare il caso come intervento operatore. Separare i blocker tecnici correggibili dai blocker documentali/business, conservare il fingerprint delle fonti e non ripetere la stessa revisione sulla stessa versione.", audit:"customerKey, modulo, blocker originari, tre passaggi di prova, regole abbinate, classificazione, fingerprint, tentativo, prossimo passo e timestamp", outcome:"continue" },
  { id:"system-apr-technical-repair-queue", kind:"system", step:"checkpoint_persistence", condition:"La revisione profonda dimostra che le fonti esistono ma APR non le ha estratte, riconciliate o mappate", sourcePrecedence:["fonti originarie locali", "checkpoint preflight", "registro unico", "test di regressione e bundle installato"], deterministicAction:"Accodare il caso come riparazione tecnica, non come intervento operatore. Una correzione generale puo riarmare il medesimo dossier soltanto quando cambia la versione del parser/regola/bundle; preservare tentativi e audit e vietare duplicazioni o azioni esterne durante la riparazione.", audit:"repairId, customerKey, blockerCode, sourceFingerprint, parser/rule revision, test, bundle SHA-256, esito replay e timestamp", outcome:"continue" },
  { id:"system-apr-learning-closure-gate", kind:"system", step:"checkpoint_persistence", condition:"Una correzione nata dall'analisi di una pratica bloccata viene proposta come comportamento riutilizzabile APR", sourcePrecedence:["blocco persistente e relativo codice diagnostico", "regola generalizzata nel registro unico", "test di regressione automatico", "bundle persistente installato"], deterministicAction:"Non dichiarare mai appresa o attiva una correzione finche' il blocco non e' collegato a un ID regola, il test della matrice corrente non e' verde, l'impronta del contenuto non coincide e i bundle supervisor/worker/watchdog installati non sono identici a quelli testati. Una risposta valida solo per il singolo cliente resta override caso-specifico e non diventa regola generale.", audit:"incidentId, practiceId/customerKey, blockerCode, ruleId, testCommand e risultato, sourceFingerprint, SHA-256 bundle costruiti/installati, stato deployment e timestamp", outcome:"continue" },
  { id:"system-final-draft-source-cardinality-and-cost-verification", kind:"system", step:"external_gate", condition:"APR sta per dichiarare completa e salvata una bozza ENEA con prodotti tecnici", sourcePrecedence:["piano tecnico APR derivato da form e fatture originarie", "riepilogo server ENEA riletto dopo l'ultimo Salva", "costo tecnico auditato"], deterministicAction:"Rileggere il riepilogo server finale e richiedere esattamente una riga distinta per ogni prodotto fisico, abbinamento 1:1 di tutti gli attributi e costo numericamente identico al valore tecnico auditato. Se manca una riga, una riga e duplicata/aggregata o il costo differisce anche di un centesimo, rifiutare lo stato bozza salvata, registrare il motivo e non eseguire preview o submit.", audit:"practiceId, draftId, conteggio atteso/osservato, indici abbinati, righe mancanti, costo atteso/osservato in centesimi, evidenceId server, esito e ID regola", outcome:"requested_operator" },
  { id:"system-apr-crm-dedicated-auth", kind:"system", step:"external_gate", condition:"Configurazione o rinnovo della sessione CRM dedicata ad APR, dopo autorizzazione esplicita dell'utente", sourcePrecedence:["risposta server di autenticazione", "refresh token APR nel Portachiavi macOS", "checkpoint privo di segreti"], deterministicAction:"Accettare credenziali soltanto dalla pagina locale loopback protetta, inviarle esclusivamente all'endpoint auth allowlist e non persistere mai la password. Conservare il solo refresh token nel Portachiavi macOS; non estrarre cookie/token da Chrome e non esporre token in file, log, API o dashboard. L'endpoint auth POST non autorizza mutazioni CRM.", audit:"origine auth, fingerprint chiave pubblicabile, fingerprint account, stato server, scadenza, servizio Portachiavi e ID regola; password e token tassativamente assenti", outcome:"requested_operator" },
  { id:"system-apr-crm-refresh-serialization-v1", kind:"system", step:"external_gate", condition:"Due processi APR possono rinnovare la stessa sessione CRM custodita nel Portachiavi", sourcePrecedence:["lock globale atomico del refresh", "refresh token corrente riletto dal Portachiavi dopo il lock", "risposta server tipizzata", "checkpoint privo di segreti"], deterministicAction:"Serializzare login e refresh in un'unica sezione critica interprocesso, rileggere il token soltanto dopo il lock e persistere la rotazione prima del rilascio. Un rifiuto di una copia superata rilegge il token corrente e ritenta una sola volta; soltanto il rifiuto definitivo 400/401 del token ancora corrente elimina la sessione. 429, 5xx, timeout e contesa del lock restano difetti tecnici temporanei e non cancellano il segreto ne diventano richieste operatore. Qualunque login_required osservato dal runner arresta subito l'intero lotto con allarme, senza attendere il timeout per-pratica e senza fabbricare un verdetto sul caso.", audit:"owner del lock, PID, acquisizione/scadenza senza token, stato HTTP tipizzato, esito rotazione, eventuale arresto lotto e ID regola", outcome:"continue" },
  { id:"system-apr-crm-readonly-adapter-contract", kind:"system", step:"external_gate", condition:"Configurazione o uso dell'adattatore CRM APR", sourcePrecedence:["configurazione versionata senza segreti", "sessione APR dedicata custodita nel Portachiavi", "allowlist origine e percorsi esatti", "fixture locale verificata"], deterministicAction:"Consentire sui dati CRM esclusivamente GET/HEAD senza corpo per coda ENEA, cliente, dossier e documenti originari. Vietare password/token nel filesystem, cookie Chrome, POST/PUT/PATCH/DELETE sui dati, pipeline, automazioni e ogni mutazione; mantenere il gate globale chiuso finché l'adattatore reale non è separatamente verificato.", audit:"config fingerprint, fixtureId, identità workspace, metodo, percorso, response fingerprint, capability e ID regola", outcome:"requested_operator" },
  { id:"system-apr-crm-integration-boundary", kind:"system", step:"external_gate", condition:"Ogni integrazione APR con il CRM PraticaRapida", sourcePrecedence:["evento CRM idempotente", "stato cliente atteso", "contratto adapter versionato"], deterministicAction:"Proporre soltanto operazioni idempotenti, auditabili e compensabili; non modificare, disabilitare o duplicare automatismi CRM e non alterare il collegamento CRM→Cruscotto.", audit:"eventId, customerId, expectedState, desiredState, idempotencyKey, compensazione, fingerprint automatismi e integrazione Cruscotto", outcome:"requested_operator" },
  { id:"system-apr-operator-intervention-routing", kind:"system", step:"runner_lifecycle", condition:"Un dossier APR è ambiguo, errato o bloccato", sourcePrecedence:["report locale del caso", "fonti originarie", "pipeline CRM Richiesto intervento operatore"], deterministicAction:"Registrare il motivo e proporre l'instradamento idempotente alla pipeline «Richiesto intervento operatore», poi proseguire la coda senza perdere il caso.", audit:"practiceId, customerId, fonti, motivo, stato precedente, comando proposto e idempotencyKey", outcome:"continue" },
  { id:"system-apr-customer-artifact-linkage", kind:"system", step:"external_gate", condition:"Futura pratica ENEA inviata con prove e artefatti disponibili", sourcePrecedence:["cliente CRM inequivoco", "prova server Inviata+CPID", "PDF/ricevuta/email ENEA"], deterministicAction:"In futuro collegare gli artefatti esclusivamente allo spazio del relativo cliente con operazioni idempotenti; nella prima versione locale vietare esecuzione, upload e comunicazioni.", audit:"customerId, practiceId, CPID, artifactId, fingerprint, operazione, compensazione e ID regola", outcome:"requested_operator" },
  { id:"system-single-active-practice", kind:"system", step:"runner_lifecycle", condition:"Ogni selezione dalla coda locale", sourcePrecedence:["checkpoint persistente corrente"], deterministicAction:"Mantenere al massimo una pratica corrente e non riselezionarla dopo un riavvio.", audit:"practiceId, revisione, idempotencyKey", outcome:"continue" },
  { id:"system-atomic-checkpoint-resume", kind:"system", step:"checkpoint_persistence", condition:"Ogni transizione o ripresa", sourcePrecedence:["ultimo checkpoint immutabile valido"], deterministicAction:"Committare atomicamente e riprendere senza ripetere una transizione già registrata.", audit:"revisione, checkpoint, regole applicate", outcome:"continue" },
  { id:"system-operator-response-ledger-concurrency-v1", kind:"system", step:"checkpoint_persistence", condition:"Due processi APR tentano di registrare quasi simultaneamente una risposta operatore o la relativa ricevuta di applicazione nello stesso ledger globale", sourcePrecedence:["lock directory esclusivo sul ledger canonico", "checkpoint valido riletto soltanto dopo l'acquisizione", "identificativo idempotente della risposta o applicazione"], deterministicAction:"Serializzare le scritture attendendo per un budget breve e limitato il rilascio di una contesa transitoria, quindi rileggere il checkpoint e applicare la mutazione idempotente. Non rilassare la validazione e fallire chiuso con apr_operator_response_ledger_busy se il lock non si libera entro il budget; errori filesystem diversi da EEXIST restano errori tecnici distinti.", audit:"percorso ledger canonico, revisione riletta, applicationId/responseId idempotente, ID regola e risultato persistito; il timeout conserva il checkpoint immutato", outcome:"continue" },
  { id:"system-draft-create-double-absence-single-retry", kind:"system", step:"external_gate", condition:"L'unico tentativo di creazione bozza ha esito non identificabile", sourcePrecedence:["eventuale bozza scoperta lato server", "due letture server autenticate e concordanti", "checkpoint durevole del tentativo"], deterministicAction:"Se una bozza esiste riprenderla; se due letture concordanti ne provano l'assenza autorizzare un solo nuovo tentativo; altrimenti isolare la pratica senza fermare la coda.", audit:"practiceId, due evidenceId server, contatore recupero, esito", outcome:"continue" },
  { id:"system-exclusive-runner-lease", kind:"system", step:"runner_lifecycle", condition:"Avvio, heartbeat o recupero del runner", sourcePrecedence:["lock locale", "lease runner persistente"], deterministicAction:"Consentire un solo proprietario; recuperare una lease scaduta conservando la pratica corrente.", audit:"ownerId, leaseUntil, motivo recupero", outcome:"continue" },
  { id:"system-operator-block-fail-closed", kind:"system", step:"external_gate", condition:"Blocco attivo o prova esterna richiesta", sourcePrecedence:["checkpoint pratica", "audit operatore"], deterministicAction:"Fermare la pratica corrente e richiedere un intervento preciso senza saltare né perdere il job.", audit:"blocco, prossima azione, practiceId", outcome:"requested_operator" },
  { id:"system-enea-lease-required", kind:"system", step:"external_gate", condition:"Passo che richiede il portale ENEA", sourcePrecedence:["lease ENEA verificata"], deterministicAction:"Non eseguire alcuna azione ENEA quando la lease non è disponibile.", audit:"stato lease, practiceId, checkpoint", outcome:"requested_operator" },
  { id:"system-readonly-adapter-contract", kind:"system", step:"external_gate", condition:"Ogni osservazione browser, CRM o ENEA", sourcePrecedence:["identità persistente registrata", "origine allowlist esatta", "risposta read-only verificata"], deterministicAction:"Accettare soltanto GET/HEAD senza corpo né intento mutativo, conservare fingerprint e metadati della prova, bloccare globalmente qualsiasi deviazione.", audit:"identità, origine, metodo, superficie, fingerprint, esito", outcome:"requested_operator" },
  { id:"system-submission-proof-required", kind:"system", step:"external_gate", condition:"Possibile completamento di un invio", sourcePrecedence:["dashboard ENEA Inviata", "CPID osservato"], deterministicAction:"Dichiarare completata una pratica soltanto con entrambe le prove; un esito incerto resta pendente e non viene ritentato.", audit:"evidenceId, dashboardStatus, CPID, observedAt", outcome:"requested_operator" },
  { id:"system-run-completed", kind:"system", step:"runner_lifecycle", condition:"Tutte le pratiche hanno prova conclusiva valida", sourcePrecedence:["checkpoint persistenti delle pratiche"], deterministicAction:"Marcare completato il run senza ulteriori selezioni.", audit:"conteggio pratiche, revisione finale", outcome:"continue" },
  { id:"system-preflight-upstream-terminal-propagation-v1", kind:"system", step:"runner_lifecycle", condition:"L'acquisizione CRM read-only e terminale ma non esiste alcun dossier con allegati elaborabili: pratica non trovata o ambigua, risposta non valida, esclusione automatica oppure zero fonti originarie", sourcePrecedence:["checkpoint acquisizione CRM terminale", "ID pratica e fingerprint risposta", "esclusione automatica registrata", "conteggio fonti originarie"], deterministicAction:"Trasformare immediatamente l'esito a monte in un preflight blocked_case coerente, con blocker strutturato e operatorQuestion, senza avviare download, analisi o ENEA; far consumare la stessa prova firmata alla revisione profonda senza attendere un modulo prodotto non applicabile. Non applicare la transizione se esiste anche un solo dossier normale con allegati elaborabili: quel caso deve attraversare la pipeline documentale completa. La coda prosegue senza attendere il timeout di liveness.", audit:"customerKey, stato acquisizione, practiceId atteso/osservato, responseSha256, esclusione, conteggio fonti, blocker, operatorQuestion, fingerprint terminale, classificazione deep review e ID regola", outcome:"continue" },
]);

const contractRules: OperationalRegistryRule[] = [
  { id:"core-screening-energy-savings", step:"enea_mapping", condition:"Schermature riconciliate 1:1 con superfici verificate", sourcePrecedence:["superfici delle righe tecniche riconciliate", "policy screening-energy-savings-v1"], deterministicAction:"Calcolare il risparmio energetico come somma delle superfici schermatura × 16,8 kWh/anno per m², arrotondata a due decimali; vietare valori non riconciliati.", audit:"righe, superfici, totale, formula, versione policy, risultato", outcome:"continue" },
  { id:"core-form-first", step:"customer_form", condition:"Ogni lavorazione", sourcePrecedence:["form cliente originario"], deterministicAction:"Acquisire il form per primo; distinguere fonte non acquisibile da dato assente.", audit:"sourceId, fingerprint, acquisizione", outcome:"continue" },
  { id:"core-economic-classification", step:"economic_sources", condition:"Sono presenti allegati", sourcePrecedence:["contenuto fiscale originario", "contenuto tecnico/non fiscale", "slot CRM soltanto come fallback fail-closed"], deterministicAction:"Classificare il contenuto prima del calcolo; per il valore ENEA di una fattura fiscale e' richiesto soltanto il totale finale stampato. Numero e data restano metadati utili all'identita e alla deduplica, mai requisiti economici o fonti di blocker.", audit:"tipo contenuto, ruolo invoice/advance/balance, totale finale, deduplica", outcome:"continue" },
  { id:"core-gross-triple-reconciliation", step:"gross_reconciliation", condition:"Calcolo spesa ENEA (contratto storico ritirato)", sourcePrecedence:["nessuna: regola sostituita dal totale finale stampato"], deterministicAction:"Non eseguire la riconciliazione tripla; il contratto resta nel registro esclusivamente per leggere audit storici.", audit:"ID regola sostitutiva e migrazione audit", outcome:"continue", lifecycle:{ status:"superseded", generalGateEligible:false, supersededByRuleId:USER_AUTHORIZED_RULE_IDS.invoiceFinalPrintedTotalRuntimeAuthority, note:"Giuliano ha ritirato definitivamente imponibile, IVA, aliquote, scadenziari e cifre intermedie come controlli o blocker ENEA l'11/09/2026." } },
  { id:"core-mapping-complete", step:"enea_mapping", condition:"Prima della preview", sourcePrecedence:["fonti originarie", "policy autorizzate"], deterministicAction:"Produrre matrice completa valore/fonte/regola/stato; nessun campo coperto da policy genera ticket.", audit:"matrice completa", outcome:"continue" },
  { id:"core-preview-required", step:"preview", condition:"Preflight dati verde", sourcePrecedence:["portale ENEA"], deterministicAction:"Aprire e verificare anteprima prima del submit.", audit:"evento anteprima", outcome:"continue" },
  { id:"core-single-submit-cpid", step:"submit_cpid", condition:"Anteprima verificata", sourcePrecedence:["stato server ENEA"], deterministicAction:"Un solo submit; successo solo Inviata con CPID; nessun retry su esito incerto.", audit:"tentativo, stato server, CPID", outcome:"continue" },
];

export const ENEA_OPERATIONAL_REGISTRY: readonly OperationalRegistryRule[] = Object.freeze([
  ...contractRules,
  ...ENEA_USER_AUTHORIZED_RULES,
  ...migratedRules,
  ...ENEA_RUNNER_SYSTEM_RULES,
]);

// Difetto strutturale (2026-09-08): ogni punto del sistema che ricalcola una
// pratica da zero decideva QUANDO farlo confrontando l'ID della revisione
// corrente con un elenco scritto a mano, esteso di volta in volta per ogni
// correzione (decine di righe per file, duplicate su piu' file). Dimenticare
// di aggiungere una riga per una correzione - come e' successo con questa
// stessa correzione prima che venisse trovato il problema - lascia le
// pratiche gia' calcolate ferme al verdetto vecchio anche dopo che il codice
// e' cambiato. Questo hash del contenuto dell'intero registro (non una
// stringa scritta a mano) cambia automaticamente ogni volta che una regola
// viene aggiunta o modificata: nessun punto del sistema deve piu' ricordarsi
// di elencare a mano le correzioni passate per sapere se ricalcolare.
export const ENEA_OPERATIONAL_REGISTRY_CONTENT_HASH = crypto.createHash("sha256")
  .update(JSON.stringify(ENEA_OPERATIONAL_REGISTRY))
  .digest("hex");

/**
 * Identificatore di revisione da passare a applyValidationRevision /
 * applyParserRevision ovunque nel sistema, al posto di un elenco scritto a
 * mano di correzioni passate. Cambia da solo a ogni modifica del registro;
 * chi lo chiama non deve mai piu' ricordarsi di aggiungere una riga.
 */
export const AUTO_CURRENT_VALIDATION_REVISION = `auto-registry-${ENEA_OPERATIONAL_REGISTRY_CONTENT_HASH}` as const;

const ENEA_OPERATIONAL_REGISTRY_BY_ID = new Map(
  ENEA_OPERATIONAL_REGISTRY.map((rule) => [rule.id, rule] as const),
);

export function rulesForStep(step: OperationalProtocolStep) { return ENEA_OPERATIONAL_REGISTRY.filter(rule=>rule.step===step); }
export function registryRule(id: string) { return ENEA_OPERATIONAL_REGISTRY_BY_ID.get(id) ?? null; }
